import { getIn, removeIn, setIn, updateIn } from "../src/index.js";

interface Deep {
  a: {
    b: {
      c: number;
      d: string[];
    };
    e: number;
  };
  list: Array<{ id: number; tags?: string[] }>;
}

const makeState = (): Deep => ({
  a: {
    b: { c: 1, d: ["x", "y", "z"] },
    e: 2,
  },
  list: [
    { id: 1, tags: ["p", "q"] },
    { id: 2 },
  ],
});

describe("getIn", () => {
  it("reads nested values via mixed paths", () => {
    const s = makeState();
    expect(getIn(s, ["a", "b", "c"])).toBe(1);
    expect(getIn(s, ["a", "b", "d", 1])).toBe("y");
    expect(getIn(s, ["list", 0, "tags", 0])).toBe("p");
    expect(getIn(s, ["a", "missing"])).toBeUndefined();
    expect(getIn(s, [])).toBe(s);
  });

  it("returns undefined when walking through primitives", () => {
    expect(getIn({ a: 3 }, ["a", "b"])).toBeUndefined();
  });
});

describe("structural sharing", () => {
  it("preserves untouched branches by reference", () => {
    const s = makeState();
    const next = setIn(s, ["a", "b", "c"], 42);

    expect(next).not.toBe(s);
    expect(next.a).not.toBe(s.a); // branch on the path was rebuilt
    expect(next.a.b).not.toBe(s.a.b);
    expect(next.a.b.c).toBe(42);
    expect(next.a.b.d).toBe(s.a.b.d); // untouched sibling array shared
    expect(next.a.e).toBe(2);
    expect(next.list).toBe(s.list); // untouched top-level branch shared
    expect(next.list[0]).toBe(s.list[0]);
  });

  it("updateIn shares untouched branches too", () => {
    const s = makeState();
    const next = updateIn(s, ["list", 1], (item) => ({
      ...item,
      tags: ["r"],
    }));

    expect(next).not.toBe(s);
    expect(next.list).not.toBe(s.list);
    expect(next.list[0]).toBe(s.list[0]); // sibling element shared
    expect(next.list[1]).toEqual({ id: 2, tags: ["r"] });
    expect(next.a.b.d).toBe(s.a.b.d);
  });
});

describe("auto-vivification", () => {
  it("creates intermediate objects keyed by strings", () => {
    const next = setIn({}, ["a", "b"], 7);
    expect(next).toEqual({ a: { b: 7 } });
  });

  it("creates intermediate arrays when next segment is numeric", () => {
    const next = setIn({}, ["a", 0, "b"], 9);
    expect(Array.isArray((next as any).a)).toBe(true);
    expect((next as any).a[0]).toEqual({ b: 9 });
  });

  it("vivifies from missing inner branches in both container types", () => {
    const next = setIn({ x: {} } as Record<string, unknown>, ["x", 2, "y"], true);
    const x = next.x as unknown[];
    expect(Array.isArray(x)).toBe(true);
    // sparse fill with undefined holes before the written index
    expect(x.length).toBe(3);
    expect(x[0]).toBeUndefined();
    expect(x[2]).toEqual({ y: true });

    const nextObj = setIn({ x: [] } as Record<string, unknown>, ["x", "k", 0], 5);
    expect((nextObj.x as any).k).toEqual([5]);
  });
});

describe("no-op identity", () => {
  it("returns original root when setting an Object.is-identical value", () => {
    const s = makeState();
    expect(setIn(s, ["a", "b", "c"], 1)).toBe(s);
    expect(setIn(s, [], s)).toBe(s);

    const arr = [1, 2, 3];
    expect(setIn(arr, [1], 2)).toBe(arr);

    // deep no-op: identical leaf anywhere down the chain
    const tags = s.list[0].tags!;
    expect(setIn(s, ["list", 0, "tags", 0], "p")).toBe(s);
    void tags;
  });

  it("updateIn is identity when fn returns an identical value", () => {
    const s = makeState();
    expect(updateIn(s, ["a", "e"], () => 2)).toBe(s);
  });

  it("distinguishes NaN correctly via Object.is semantics", () => {
    const s = { n: NaN };
    expect(setIn(s, ["n"], NaN)).toBe(s);
    expect(setIn(s, ["n"], 0)).not.toBe(s);
  });
});

describe("array splice semantics", () => {
  it("removeIn splices the index out instead of leaving a hole", () => {
    const s = makeState();
    const next = removeIn(s, ["a", "b", "d", 1]);

    expect(next).not.toBe(s);
    expect(next.a.b.d).toEqual(["x", "z"]);
    expect(1 in next.a.b.d).toBe(true); // no sparse hole at removed position
    expect(next.a.b.d).not.toBe(s.a.b.d);
    expect(next.a.b).not.toBe(s.a.b);
    expect(s.a.b.d).toEqual(["x", "y", "z"]); // original untouched

    // siblings above still shared
    expect(next.list).toBe(s.list);
    expect(next.a.e).toBe(2);
  });

  it("removing the only element empties the array", () => {
    const next = removeIn([["only"]], [0]);
    expect(next).toEqual([]);
  });
});

describe("removeIn misc", () => {
  it("removes object keys, sharing siblings", () => {
    const s = makeState();
    const next = removeIn(s, ["a", "b"]);
    expect(Object.hasOwn(next.a, "b")).toBe(false);
    expect(next.a.e).toBe(2);
    expect(next.list).toBe(s.list);
    expect(next.a).not.toBe(s.a);
  });

  it("is a no-op for missing keys / out-of-range indices", () => {
    const s = makeState();
    expect(removeIn(s, ["nope"])).toBe(s);
    expect(removeIn(s, ["a", "b", "d", 99])).toBe(s);
    expect(removeIn(null, ["a"])).toBe(null);
  });
});

describe("TypeScript typing", () => {
  it("keeps the returned type equal to the input type", () => {
    const s = makeState();
    const next: Deep = setIn(s, ["a", "b", "c"], 99);
    expect(next.a.b.c).toBe(99);

    const upd: Deep = updateIn(s, ["a", "e"], (n) => (n as number) + 1);
    expect(upd.a.e).toBe(3);

    const rem: Deep = removeIn(s, ["list", 0, "id"]);
    expect(rem.list.length).toBe(2);

    // typed read back
    const c: unknown = getIn(next, ["a", "b", "c"]);
    expect(c).toBe(99);
  });
});
