status: ok
/**
 * Path-based immutable update helpers for nested state.
 *
 * All operations are persistent: unchanged branches are shared with the
 * original structure by reference (structural sharing). If an operation
 * does not change anything (the new value is `Object.is`-identical to the
 * existing one), the original root object is returned untouched.
 */

export type PathSegment = string | number;
export type Path = readonly PathSegment[];

const isIndex = (seg: PathSegment): seg is number => typeof seg === "number";

function makeContainer(key: PathSegment): Record<string | number, unknown> {
  return (isIndex(key) ? [] : {}) as Record<string | number, unknown>;
}

/**
 * Copy `container` so the slot `key` can be written. Existing containers keep
 * their kind; missing/primitive slots are vivified, and an *empty* container
 * whose kind mismatches `key` (numeric -> array, string -> object) is retyped,
 * since there is no data to lose.
 */
function copyForWrite(cur: unknown, key: PathSegment): Record<string | number, unknown> | unknown[] {
  if (cur !== null && typeof cur === "object") {
    const isArray = Array.isArray(cur);
    const empty = isArray ? (cur as unknown[]).length === 0 : Object.keys(cur).length === 0;
    if (empty && isArray !== isIndex(key)) return makeContainer(key);
    return isArray ? (cur as unknown[]).slice() : { ...(cur as Record<string | number, unknown>) };
  }
  return makeContainer(key);
}

function setAt(cur: unknown, path: Path, value: unknown): unknown {
  const [seg, ...rest] = path;

  if (rest.length === 0) {
    // Leaf write.
    if (cur !== null && typeof cur === "object") {
      if (Array.isArray(cur)) {
        if (!isIndex(seg)) throw new TypeError("Numeric index required for array paths");
        if (seg in cur && Object.is(cur[seg], value)) return cur;
        const copy = cur.slice();
        copy[seg] = value;
        return copy;
      }
      const rec = cur as Record<string | number, unknown>;
      if (seg in rec && Object.is(rec[seg], value)) return cur;
      const copy = { ...rec };
      copy[seg] = value;
      return copy;
    }
    // Vivify a missing/primitive slot into a container and write the leaf.
    if (value === undefined) return cur; // nothing to materialize
    const seed = makeContainer(seg);
    seed[seg] = value;
    return seed;
  }

  // Intermediate level: recurse first so we can bail out on no-op children.
  const child = cur !== null && typeof cur === "object" ? (cur as Record<PathSegment, unknown>)[seg] : undefined;
  const nextChild = setAt(child, rest, value);
  if (
    child !== null &&
    typeof child === "object" &&
    nextChild === child
  ) {
    return cur; // child unchanged -> share this branch
  }

  const container = copyForWrite(cur, seg);
  (container as Record<string | number, unknown>)[seg] = nextChild;
  return container;
}



/** Read the value at `path`; returns `undefined` for missing segments. */
export function getIn(obj: unknown, path: Path): unknown {
  let cur: unknown = obj;
  for (const seg of path) {
    if (cur === null || cur === undefined) return undefined;
    cur = (cur as Record<PathSegment, unknown>)[seg];
  }
  return cur;
}

/** Set the value at `path`, creating intermediate containers as needed. */
export function setIn<T>(obj: T, path: Path, value: unknown): T {
  if (path.length === 0) {
    // Replacing the root itself: identity only when nothing changes.
    return Object.is(obj, value) ? obj : (value as T);
  }
  return setAt(obj as unknown, path, value) as T;
}

/** Apply `fn` to the value at `path`. Identity-preserving if `fn` returns an equal value. */
export function updateIn<T>(obj: T, path: Path, fn: (value: unknown) => unknown): T {
  return setIn(obj, path, fn(getIn(obj, path)));
}

/** Remove the key/index at `path`. Array indices are spliced out, leaving no holes. */
export function removeIn<T>(obj: T, path: Path): T {
  if (path.length === 0) return obj;
  return removeAt(obj as unknown, path) as T;
}

function removeAt(cur: unknown, path: Path): unknown {
  const [seg, ...rest] = path;

  if (cur === null || cur === undefined) return cur;

  if (Array.isArray(cur)) {
    if (!isIndex(seg)) return cur;
    if (rest.length === 0) {
      if (!(seg in cur)) return cur; // out of range / hole already: no-op
      const copy = cur.slice();
      copy.splice(seg, 1); // splice: indices shift, no sparse hole
      return copy;
    }
    if (!(seg in cur)) return cur;
    const nextChild = removeAt(cur[seg], rest);
    if (nextChild === cur[seg]) return cur;
    const copy = cur.slice();
    copy[seg] = nextChild;
    return copy;
  }

  if (typeof cur !== "object") return cur;

  const rec = cur as Record<string | number, unknown>;
  if (rest.length === 0) {
    if (!(seg in rec)) return cur;
    const copy = { ...rec };
    delete copy[seg];
    return copy;
  }
  if (!(seg in rec)) return cur;
  const nextChild = removeAt(rec[seg], rest);
  if (nextChild === rec[seg]) return cur;
  const copy = { ...rec };
  copy[seg] = nextChild;
  return copy;
}
